/** @param {NS} ns */
export async function main(ns) {
  const visited = new Set();
  const queue = ['home'];
  const hosts = [];

  while (queue.length > 0) {
    const host = queue.shift();
    if (visited.has(host)) continue;
    visited.add(host);
    hosts.push(host);

    const neighbors = ns.scan(host);
    for (const neighbor of neighbors) {
      if (!visited.has(neighbor)) queue.push(neighbor);
    }
  }

  ns.tprint('=== Server Discovery ===');
  for (const host of hosts) {
    const maxMoney = ns.getServerMaxMoney(host);
    const money = ns.getServerMoneyAvailable(host);
    const minSec = ns.getServerMinSecurityLevel(host);
    const sec = ns.getServerSecurityLevel(host);
    const hackLvl = ns.getServerRequiredHackingLevel(host);
    const root = ns.hasRootAccess(host);
    const ports = ns.getServerNumPortsRequired(host);

    const maxMStr = maxMoney > 1e12 ? (maxMoney/1e12).toFixed(2)+'t' : maxMoney > 1e9 ? (maxMoney/1e9).toFixed(1)+'b' : (maxMoney/1e6).toFixed(0)+'m';
    const monStr = money > 1e12 ? (money/1e12).toFixed(2)+'t' : money > 1e9 ? (money/1e9).toFixed(1)+'b' : (money/1e6).toFixed(0)+'m';

    ns.tprint(`${host.padEnd(20)} | max:${maxMStr.padEnd(6)} cur:${monStr.padEnd(6)} | minSec:${minSec.toFixed(1)} cur:${sec.toFixed(1)} | lvl:${hackLvl} | root:${root} | ports:${ports}`);
  }
}

/** @param {NS} ns */
export async function main(ns) {
  const RESCAN_INTERVAL = 30000;
  const ACTION_DELAY = 100;
  let lastRescan = 0;
  let target = null;

  while (true) {
    const now = Date.now();

    // Rescan for targets periodically
    if (now - lastRescan > RESCAN_INTERVAL) {
      lastRescan = now;
      target = findBestTarget(ns);
      if (target) {
        ns.print(`[RESCAN] Chose target: ${target}`);
      }
    }

    // If no target yet, try to find one
    if (!target) {
      target = findBestTarget(ns);
      if (!target) {
        ns.print(`[WAIT] No suitable target found`);
        await ns.sleep(1000);
        continue;
      }
    }

    // Execute action on current target
    const minSec = ns.getServerMinSecurityLevel(target);
    const curSec = ns.getServerSecurityLevel(target);
    const maxMoney = ns.getServerMaxMoney(target);
    const curMoney = ns.getServerMoneyAvailable(target);

    if (curSec > minSec + 5) {
      await ns.weaken(target);
      ns.print(`[WEAKEN] ${target}: sec ${curSec.toFixed(1)} > ${(minSec + 5).toFixed(1)}`);
    } else if (curMoney < maxMoney * 0.75) {
      await ns.grow(target);
      ns.print(`[GROW] ${target}: $${(curMoney / 1e6).toFixed(1)}M / $${(maxMoney / 1e6).toFixed(1)}M`);
    } else {
      await ns.hack(target);
      ns.print(`[HACK] ${target}`);
    }

    await ns.sleep(ACTION_DELAY);
  }
}

function findBestTarget(ns) {
  const playerLevel = ns.getHackingLevel();
  let best = null;
  let bestMoney = 0;

  const queue = ['home'];
  const visited = new Set();

  while (queue.length > 0) {
    const server = queue.shift();
    if (visited.has(server)) continue;
    visited.add(server);

    if (server !== 'home') {
      if (!ns.hasRootAccess(server)) continue;

      const maxMoney = ns.getServerMaxMoney(server);
      if (maxMoney <= 0) continue;

      const reqLevel = ns.getServerRequiredHackingLevel(server);
      if (reqLevel > playerLevel) continue;

      if (maxMoney > bestMoney) {
        best = server;
        bestMoney = maxMoney;
      }
    }

    const neighbors = ns.scan(server);
    for (const neighbor of neighbors) {
      if (!visited.has(neighbor)) {
        queue.push(neighbor);
      }
    }
  }

  return best;
}

/** @param {NS} ns */
export async function main(ns) {
  const hosts = ns.scan("home");
  const level = ns.getHackingLevel();
  let best = null;
  let bestScore = -1;

  for (const h of hosts) {
    if (!ns.hasRootAccess(h)) continue;
    const mm = ns.getServerMaxMoney(h);
    if (mm <= 0) continue;
    const req = ns.getServerRequiredHackingLevel(h);
    if (req > level) continue;
    const score = mm * 1e9 - req;
    if (score > bestScore) {
      bestScore = score;
      best = h;
    }
  }

  if (best) {
    ns.tprint(`Target: ${best}`);
    ns.tprint(`MaxMoney: ${ns.getServerMaxMoney(best)}`);
    ns.tprint(`CurrentMoney: ${ns.getServerMoneyAvailable(best)}`);
    ns.tprint(`MinSec: ${ns.getServerMinSecurityLevel(best)}`);
    ns.tprint(`CurrentSec: ${ns.getServerSecurityLevel(best)}`);
    ns.tprint(`ReqLevel: ${ns.getServerRequiredHackingLevel(best)}`);
    ns.tprint(`Reachable: ${hosts.slice(0,5).join(", ")}`);
  } else {
    ns.tprint("No valid targets");
  }
}

/** @param {NS} ns */
export async function main(ns) {
  const scan = (h) => ns.scan(h);
  const lvl = ns.getHackingLevel();
  let target = '';
  let cycle = 0;

  while(true) {
    if(cycle % 20 === 0) {
      let best = '', maxMon = 0;
      const q = ['home'];
      const seen = new Set(['home']);
      while(q.length) {
        const curr = q.shift();
        for(const next of scan(curr)) {
          if(!seen.has(next)) {
            seen.add(next);
            q.push(next);
            if(ns.hasRootAccess(next)) {
              const mon = ns.getServerMaxMoney(next);
              const req = ns.getServerRequiredHackingLevel(next);
              if(mon > 0 && req <= lvl && mon > maxMon) {
                maxMon = mon;
                best = next;
              }
            }
          }
        }
      }
      target = best;
    }

    if(!target) {
      await ns.sleep(100);
      cycle++;
      continue;
    }

    const minSec = ns.getServerMinSecurityLevel(target);
    const curSec = ns.getServerSecurityLevel(target);
    const maxMon = ns.getServerMaxMoney(target);
    const curMon = ns.getServerMoneyAvailable(target);

    if(curSec > minSec + 5) {
      await ns.weaken(target);
    } else if(curMon < 0.75 * maxMon) {
      await ns.grow(target);
    } else {
      await ns.hack(target);
    }

    cycle++;
    if(cycle % 10 === 0) {
      ns.tprint(`[${cycle}] ${target}: sec=${curSec.toFixed(1)} mon=${curMon.toFixed(0)}`);
    }
  }
}

